/**
 * The props passed to a custom `errorTemplate` component for the `ToolCall` component.
 *
 * When an `errorTemplate` is provided, it replaces the default error message rendering.
 */
export interface ToolCallErrorTemplateProps {
    /** The error message text. */
    errorText?: string;
}
